inline bool VerifyCOTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<COT>(COTIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedCOTBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<COT>(COTIdentifier());
}

inline void FinishCOTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<COT> root) {
  fbb.Finish(root, COTIdentifier());
}

inline void FinishSizePrefixedCOTBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<COT> root) {
  fbb.FinishSizePrefixed(root, COTIdentifier());
}

inline std::unique_ptr<COTT> UnPackCOT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<COTT>(GetCOT(buf)->UnPack(res));
}

inline std::unique_ptr<COTT> UnPackSizePrefixedCOT(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<COTT>(GetSizePrefixedCOT(buf)->UnPack(res));
}

#endif  // FLATBUFFERS_GENERATED_COT_MAIN_H_
